pub type AndroidSocketPolicy = extern "C" fn(fd: std::ffi::c_int, source: u32) -> std::ffi::c_int;

#[cfg(target_os = "android")]
static ANDROID_SOCKET_POLICY: std::sync::RwLock<Option<AndroidSocketPolicy>> =
    std::sync::RwLock::new(None);

#[cfg(target_os = "android")]
pub fn set_android_socket_policy(policy: Option<AndroidSocketPolicy>) {
    *ANDROID_SOCKET_POLICY.write().unwrap() = policy;
}

#[cfg(target_os = "android")]
fn prepare_android_socket(socket: &socket2::Socket, source: IpAddr) -> std::io::Result<()> {
    use std::os::fd::AsRawFd;
    use nix::libc;

    let Some(policy) = *ANDROID_SOCKET_POLICY.read().unwrap() else {
        return Ok(());
    };
    let IpAddr::V4(source) = source else {
        return Err(std::io::ErrorKind::PermissionDenied.into());
    };
    let fd = socket.as_raw_fd();
    let interface = policy(fd, u32::from(source));
    if interface < 0 {
        return Err(std::io::ErrorKind::PermissionDenied.into());
    }
    if interface == 0 {
        return Ok(());
    }

    // A tethering downstream often has no Android Network handle. The Linux
    // unicast interface option pins IPv4 egress without SO_BINDTODEVICE.
    const IP_UNICAST_IF: libc::c_int = 50;
    let index = (interface as u32).to_be();
    let result = unsafe {
        libc::setsockopt(
            fd, libc::IPPROTO_IP, IP_UNICAST_IF,
            (&index as *const u32).cast(), std::mem::size_of_val(&index) as libc::socklen_t,
        )
    };
    if result != 0 {
        return Err(std::io::Error::last_os_error());
    }
    Ok(())
}

