    std::sync::RwLock::new(None);

extern "C" fn prepare_socket(fd: jint, source: u32) -> jint {
    let policy = SOCKET_POLICY.read().unwrap();
    let Some((vm, callback)) = policy.as_ref() else {
        return -1;
    };
    let Ok(mut env) = vm.attach_current_thread() else {
        return -1;
    };
    let result = (|| {
        let address = env.new_string(std::net::Ipv4Addr::from(source).to_string())?;
        let address = JObject::from(address);
        env.call_method(callback.as_obj(), "prepare", "(ILjava/lang/String;)I",
            &[JValue::Int(fd), JValue::Object(&address)])?.i()
    })();
    if env.exception_check().unwrap_or(false) {
        let _ = env.exception_clear();
    }
    result.unwrap_or(-1)
}

