) -> jint {
    if policy.is_null() {
        unsafe { wikall_set_android_socket_policy(None) };
        *SOCKET_POLICY.write().unwrap() = None;
        return 0;
    }
    let (Ok(vm), Ok(callback)) = (env.get_java_vm(), env.new_global_ref(policy)) else {
        return -1;
    };
    *SOCKET_POLICY.write().unwrap() = Some((vm, callback));
